async function removePhoto(caseId, photoId) { if (!confirm('Remove this reference photo? It will be permanently deleted from this recovery case.')) return; try { await api(`/cases/${caseId}/photos/${photoId}/delete`,{method:'POST'}); await loadPhotos(cases.filter(record=>record.id===caseId)); render(); renderModalPhotos(); toast('Reference photo removed','The private photo was permanently removed.'); } catch(error) { toast('Unable to remove photo',error.message||'Please try again.'); } }
