document.addEventListener('keydown',event=>{const card=event.target.closest('[data-action="detail"],[data-action="vault-detail"]');if(card&&(event.key==='Enter'||event.key===' ')){event.preventDefault();card.click();}if(event.key==='Escape'){$('#authModal')?.classList.remove('open');finishVaultConfirmation(false);$('#caseModal')?.classList.remove('open');$('#vaultModal')?.classList.remove('open');$('#transferModal')?.classList.remove('open');$('#vaultRecoveryModal')?.classList.remove('open');}});
async function init(){if(location.protocol==='file:'){render();return;}if(window.LOCKX_LOCAL_PREVIEW){session={access_token:'local-preview',user:{email:'Local preview'}};render();go('lost-found');return;}setupCaseModal();setupVaultModal();ensureDetail();ensureVaultDetail();$('#transferForm').addEventListener('submit',saveTransfer);$('#vaultRecoveryForm').addEventListener('submit',submitVaultRecovery);try{await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2';script.onload=resolve;script.onerror=reject;document.head.append(script);});client=window.supabase.createClient(SUPABASE_URL,SUPABASE_KEY);session=(await client.auth.getSession()).data.session;client.auth.onAuthStateChange((_event,next)=>{session=next;window.dispatchEvent(new Event('lockx-session'));});await refresh();go(['#lost-found','#found'].includes(location.hash)?'lost-found':session?'dashboard':'landing');}catch{go(['#lost-found','#found'].includes(location.hash)?'lost-found':'landing');toast('Workspace unavailable','LockX could not initialize securely. Refresh and try again.');}}
init();
